-- Routing and codes live on `tables` (adjustments T1; D95; T79): the connector's `places` stop
-- carrying a QR token and a label. Generated by drizzle-kit (the drops), with the re-copy written
-- by hand: 0020 copied every served place's token and label into its table, but code that ran
-- between the two migrations still wrote them on the place, so the place's values are taken as
-- the truth one last time (a token that differs replaces the table's; a cleared one clears it),
-- then the columns go. Both tables stop forcing row-level security on their owner for the length
-- of this transaction, and `tables` stops touching `updated_at`.

ALTER TABLE "restro"."places" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."tables" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."tables" DISABLE TRIGGER "tables_touch_updated_at";--> statement-breakpoint

-- Names first (a name may be set on a table whose number is null, never cleared on one).
UPDATE "restro"."tables" t
SET "name" = nullif(btrim(p."label"), '')
FROM "restro"."places" p
WHERE p."table_id" = t."id"
  AND nullif(btrim(p."label"), '') IS DISTINCT FROM t."name"
  AND (nullif(btrim(p."label"), '') IS NOT NULL OR t."number" IS NOT NULL);--> statement-breakpoint
-- Tokens: clear what differs, then copy (two steps keep `tables_qr_token_unique` satisfied).
UPDATE "restro"."tables" t
SET "qr_token" = NULL
FROM "restro"."places" p
WHERE p."table_id" = t."id" AND p."qr_token" IS DISTINCT FROM t."qr_token";--> statement-breakpoint
UPDATE "restro"."tables" t
SET "qr_token" = p."qr_token"
FROM "restro"."places" p
WHERE p."table_id" = t."id" AND p."qr_token" IS NOT NULL AND t."qr_token" IS NULL;--> statement-breakpoint

ALTER TABLE "restro"."tables" ENABLE TRIGGER "tables_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."tables" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."places" FORCE ROW LEVEL SECURITY;--> statement-breakpoint

ALTER TABLE "restro"."places" DROP CONSTRAINT "places_qr_token_unique";--> statement-breakpoint
ALTER TABLE "restro"."places" DROP CONSTRAINT "places_label_length";--> statement-breakpoint
ALTER TABLE "restro"."places" DROP CONSTRAINT "places_qr_token_format";--> statement-breakpoint
ALTER TABLE "restro"."places" DROP COLUMN "qr_token";--> statement-breakpoint
ALTER TABLE "restro"."places" DROP COLUMN "label";
